pub struct LlmConfig {
    pub mode: LlmMode,
    pub base_url: String,
    pub api_key: Option<String>,
    pub model_fast: String,
    pub model_mid: String,
    pub model_strong: String,
    pub timeout_ms: u64,
    pub temperature: f32,
    pub max_tokens: Option<u32>,
